using Michaelhouse.Mobile.Models;
using Michaelhouse.Mobile.Services;
using ZXing.Net.Maui;
using ZXing.Net.Maui.Controls;
namespace Michaelhouse.Mobile.Pages;
public sealed class LoginPage : ContentPage { readonly Entry email=new(){Placeholder="Email"}; readonly Entry password=new(){Placeholder="Password",IsPassword=true}; readonly Label msg=new(){TextColor=Colors.Firebrick}; readonly MobileApiClient api; readonly SessionService session; public LoginPage(MobileApiClient a,SessionService s){api=a;session=s;Content=new VerticalStackLayout{Padding=28,Children={new Image{Source="michaelhouse_logo.png",HeightRequest=90},new Label{Text="Michaelhouse",Style=(Style)Application.Current!.Resources["Headline"]},email,password,new Button{Text="Sign in",Command=new Command(async()=>await Go())},msg}};} async Task Go(){try{msg.Text="Signing in…";var x=await api.PostAsync<LoginResponse>("auth/login",new{email=email.Text,password=password.Text});if(String.IsNullOrEmpty(x?.Token))throw new InvalidOperationException("The server did not return a login token.");await session.SaveAsync(x.Token);api.SetToken(x.Token);Page page=String.Equals(x.Role,"Teacher",StringComparison.OrdinalIgnoreCase)?new TeacherSessionsPage(api,session,x.Name):String.Equals(x.Role,"Driver",StringComparison.OrdinalIgnoreCase)?new DriverTripsPage(api,session,x.Name):String.Equals(x.Role,"HouseMaster",StringComparison.OrdinalIgnoreCase)?new HouseMasterHomePage(api,session,x.Name):String.Equals(x.Role,"Student",StringComparison.OrdinalIgnoreCase)?new DashboardPage(api,session,x.Name):throw new InvalidOperationException("This mobile portal is not available to this account.");await Navigation.PushAsync(page);Navigation.RemovePage(this);}catch(Exception ex){msg.Text=String.IsNullOrWhiteSpace(ex.Message)?"Sign-in failed.":ex.Message;}} }
public sealed class DashboardPage : ContentPage { public DashboardPage(MobileApiClient a,SessionService s,string n){Title="Michaelhouse";Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text="Welcome, "+n,Style=(Style)Application.Current!.Resources["Headline"],HorizontalTextAlignment=TextAlignment.Start},B("My profile",()=>Navigation.PushAsync(new StudentProfilePage(a))),B("Timetable",()=>Navigation.PushAsync(new StudentTimetablePage(a))),B("Results",()=>Navigation.PushAsync(new StudentResultsPage(a))),B("Attendance",()=>Navigation.PushAsync(new StudentAttendancePage(a))),B("Alerts",()=>Navigation.PushAsync(new StudentAlertsPage(a))),B("Sign out",async()=>{s.Clear();a.SetToken(null);await Navigation.PushAsync(new LoginPage(a,s));})}};} static Button B(string t,Func<Task> f)=>new(){Text=t,Command=new Command(async()=>await f())}; }
public sealed class StudentSearchPage : ContentPage { readonly MobileApiClient api; readonly Entry q=new(){Placeholder="Search name or student number"}; readonly CollectionView list=new(); readonly Label state=new(); public StudentSearchPage(MobileApiClient a){api=a;Title="Students";list.SelectionChanged+=async(_,e)=>{if(e.CurrentSelection.FirstOrDefault()is StudentDto s)await Navigation.PushAsync(new StudentDetailsPage(api,s.StudentId));};Content=new VerticalStackLayout{Padding=16,Children={q,new Button{Text="Search",Command=new Command(async()=>await Load())},state,list}};} async Task Load(){try{var x=await api.GetAsync<List<StudentDto>>("students?search="+Uri.EscapeDataString(q.Text??""))??[];list.ItemsSource=x;state.Text=x.Count==0?"No students found.":"";}catch{state.Text="Unable to load students.";}} }
public sealed class StudentDetailsPage : ContentPage { readonly MobileApiClient api; readonly int id; readonly Label info=new(); public StudentDetailsPage(MobileApiClient a,int i){api=a;id=i;Content=new VerticalStackLayout{Padding=16,Children={info,new Button{Text="Residence assignment",Command=new Command(async()=>await Navigation.PushAsync(new ResidenceMovementPage(api,id)))}}};} protected override async void OnAppearing(){base.OnAppearing();try{var s=await api.GetAsync<StudentDto>($"students/{id}");info.Text=$"{s?.Name}\n{s?.StudentNumber}\n{s?.Grade}";}catch{info.Text="Unable to load student.";}} }
public sealed class ResidenceAssignmentPage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); public ResidenceAssignmentPage(MobileApiClient a){api=a;Content=list;} protected override async void OnAppearing(){base.OnAppearing();try{list.ItemsSource=await api.GetAsync<List<ResidenceDto>>("residences")??[];}catch{}} }
public sealed class ResidenceMovementPage : ContentPage { readonly MobileApiClient api; readonly int id; readonly Entry room=new(){Placeholder="Target room ID",Keyboard=Keyboard.Numeric}; readonly Label result=new(); public ResidenceMovementPage(MobileApiClient a,int i){api=a;id=i;Content=new VerticalStackLayout{Padding=16,Children={result,room,new Button{Text="Move student",Command=new Command(async()=>await Move())}}};} protected override async void OnAppearing(){base.OnAppearing();try{var a=await api.GetAsync<AssignmentDto>($"students/{id}/assignment");result.Text=a==null?"No active assignment.":$"{a.Residence?.Name}, room {a.Room?.RoomNumber}";}catch{result.Text="Unable to load assignment.";}} async Task Move(){if(!Int32.TryParse(room.Text,out var r)){result.Text="Enter room ID.";return;}try{await api.PostAsync<object>("residence/move",new{studentId=id,targetRoomId=r,reason="Mobile move"});result.Text="Student moved.";}catch{result.Text="Move failed.";}} }
public sealed class QRScannerPage : ContentPage { readonly MobileApiClient api; readonly Label result=new(); bool scanning; public QRScannerPage(MobileApiClient api){this.api=api;Title="QR Scanner";var camera=new CameraBarcodeReaderView{IsDetecting=true,Options=new BarcodeReaderOptions{ Formats = BarcodeFormats.All } };camera.BarcodesDetected+=OnBarcodesDetected;Content=new Grid{RowDefinitions={new RowDefinition{Height=GridLength.Star},new RowDefinition{Height=GridLength.Auto}},Children={camera,result}};Grid.SetRow(result,1);} void OnBarcodesDetected(object? sender,BarcodeDetectionEventArgs e){var code=e.Results.FirstOrDefault()?.Value;if(scanning||String.IsNullOrWhiteSpace(code))return;scanning=true;MainThread.BeginInvokeOnMainThread(async()=>{try{var response=await api.PostAsync<ScanResponse>("qr/scan",new{qrValue=code});result.Text=response?.Approved==true?"Approved: "+response.Reason:"Declined: "+response?.Reason;}catch(Exception ex){result.Text=ex.Message;}finally{scanning=false;}});} sealed class ScanResponse{public bool Approved{get;set;}public string Reason{get;set;}="";} }

public sealed class StudentProfilePage : ContentPage { readonly MobileApiClient api; readonly Label detail=new(); public StudentProfilePage(MobileApiClient a){api=a;Title="My profile";Content=new VerticalStackLayout{Padding=20,Children={detail}};} protected override async void OnAppearing(){base.OnAppearing();try{var s=await api.GetAsync<StudentDto>("student/profile");detail.Text=s==null?"Profile unavailable.":$"{s.Name}\n{s.StudentNumber}\n{s.Grade}";}catch{detail.Text="Unable to load your profile.";}} }
public sealed class StudentTimetablePage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public StudentTimetablePage(MobileApiClient a){api=a;Title="Timetable";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Subject").Bind(TextCell.DetailProperty,"Period"));Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<TimetableSlotDto>>("student/timetable")??[];list.ItemsSource=x;state.Text=x.Count==0?"No timetable is available.":"";}catch{state.Text="Unable to load the timetable.";}} }
public sealed class StudentResultsPage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public StudentResultsPage(MobileApiClient a){api=a;Title="Results";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Subject").Bind(TextCell.DetailProperty,new Binding("Percentage",stringFormat:"{0}%")));Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<ResultDto>>("student/results")??[];list.ItemsSource=x;state.Text=x.Count==0?"Results are not yet available.":"";}catch{state.Text="Unable to load results.";}} }
public sealed class StudentAttendancePage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public StudentAttendancePage(MobileApiClient a){api=a;Title="Attendance";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Subject").Bind(TextCell.DetailProperty,"Status"));Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<AttendanceDto>("student/attendance");list.ItemsSource=x?.Records;state.Text=x==null||x.Records.Count==0?"No attendance records are available.":"";}catch{state.Text="Unable to load attendance.";}} }
public sealed class StudentAlertsPage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public StudentAlertsPage(MobileApiClient a){api=a;Title="Alerts";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Message").Bind(TextCell.DetailProperty,"CreatedAt"));Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<AlertDto>>("student/alerts")??[];list.ItemsSource=x;state.Text=x.Count==0?"You have no alerts.":"";}catch{state.Text="Unable to load alerts.";}} }

public sealed class TeacherSessionsPage : ContentPage { readonly MobileApiClient api; readonly SessionService session; readonly CollectionView list=new(); readonly Label state=new(); public TeacherSessionsPage(MobileApiClient a,SessionService s,string name){api=a;session=s;Title="Attendance";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Subject").Bind(TextCell.DetailProperty,"Grade"));list.SelectionChanged+=async(_,e)=>{if(e.CurrentSelection.FirstOrDefault()is TeacherSessionDto x)await Navigation.PushAsync(new TeacherRegisterPage(api,x));};Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text="My classes",Style=(Style)Application.Current!.Resources["Headline"],HorizontalTextAlignment=TextAlignment.Start},state,list,new Button{Text="Sign out",Command=new Command(async()=>{session.Clear();api.SetToken(null);await Navigation.PushAsync(new LoginPage(api,session));})}}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<TeacherSessionDto>>("teacher/sessions")??[];list.ItemsSource=x;state.Text=x.Count==0?"No assigned classes are available.":"";}catch{state.Text="Unable to load your classes.";}} }
public sealed class TeacherRegisterPage : ContentPage { readonly MobileApiClient api; readonly TeacherSessionDto session; readonly VerticalStackLayout rows=new(){Spacing=8}; readonly Label state=new(); readonly Dictionary<int,Picker> choices=new(); DateTime date; public TeacherRegisterPage(MobileApiClient a,TeacherSessionDto s){api=a;session=s;Title=s.Subject;Content=new ScrollView{Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text=$"{s.Subject} · Grade {s.Grade}",Style=(Style)Application.Current!.Resources["SubHeadline"],HorizontalTextAlignment=TextAlignment.Start},state,rows,new Button{Text="Save attendance",Command=new Command(async()=>await Save())}}}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<TeacherRegisterDto>($"teacher/sessions/{session.SubjectId}/attendance");if(x==null){state.Text="Register unavailable.";return;}date=x.Date;rows.Children.Clear();choices.Clear();foreach(var student in x.Students){var picker=new Picker{Title="Status",ItemsSource=new List<string>{"Present","Absent","Late"},SelectedItem=student.Status};choices[student.StudentId]=picker;rows.Children.Add(new Border{Padding=12,Content=new VerticalStackLayout{Children={new Label{Text=student.Name,FontAttributes=FontAttributes.Bold},picker}}});}}catch{state.Text="Unable to load the register.";}} async Task Save(){try{state.Text="Saving…";var students=choices.Select(x=>new{studentId=x.Key,status=x.Value.SelectedItem?.ToString()??"Present"});await api.PostAsync<object>($"teacher/sessions/{session.SubjectId}/attendance",new{date,students});state.Text="Attendance saved.";}catch(Exception ex){state.Text=String.IsNullOrWhiteSpace(ex.Message)?"Unable to save attendance.":ex.Message;}} }
public sealed class DriverTripsPage : ContentPage { readonly MobileApiClient api; readonly SessionService session; readonly CollectionView trips=new(); readonly Label state=new(); public DriverTripsPage(MobileApiClient a,SessionService s,string name){api=a;session=s;Title="My trips";trips.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Title").Bind(TextCell.DetailProperty,"ScheduledDate"));trips.SelectionChanged+=async(_,e)=>{if(e.CurrentSelection.FirstOrDefault()is DriverTripDto x)await Navigation.PushAsync(new DriverManifestPage(api,x));};Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text="Assigned trips",Style=(Style)Application.Current!.Resources["Headline"],HorizontalTextAlignment=TextAlignment.Start},state,trips,new Button{Text="Sign out",Command=new Command(async()=>{session.Clear();api.SetToken(null);await Navigation.PushAsync(new LoginPage(api,session));})}}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<DriverTripDto>>("driver/trips")??[];trips.ItemsSource=x;state.Text=x.Count==0?"No active trips are assigned to you.":"";}catch{state.Text="Unable to load assigned trips.";}} }
public sealed class DriverManifestPage : ContentPage { readonly MobileApiClient api; readonly DriverTripDto trip; readonly CollectionView students=new(); readonly Label state=new(); public DriverManifestPage(MobileApiClient a,DriverTripDto t){api=a;trip=t;Title=t.Title;students.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Name").Bind(TextCell.DetailProperty,"Boarded"));Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text=t.Title,Style=(Style)Application.Current!.Resources["SubHeadline"],HorizontalTextAlignment=TextAlignment.Start},state,students,new Button{Text="Scan boarding QR",Command=new Command(async()=>await Navigation.PushAsync(new DriverQrScanPage(api,trip,"before"))},new Button{Text="Scan return QR",Command=new Command(async()=>await Navigation.PushAsync(new DriverQrScanPage(api,trip,"after"))}}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<DriverManifestDto>($"driver/trips/{trip.Id}/manifest");students.ItemsSource=x?.Students;state.Text=x==null||x.Students.Count==0?"No students are expected on this trip.":"";}catch{state.Text="Unable to load trip manifest.";}} }
public sealed class DriverQrScanPage : ContentPage { readonly MobileApiClient api; readonly DriverTripDto trip; readonly string phase; readonly Label result=new(){FontAttributes=FontAttributes.Bold}; bool scanning; public DriverQrScanPage(MobileApiClient a,DriverTripDto t,string p){api=a;trip=t;phase=p;Title=p=="before"?"Boarding scan":"Return scan";var camera=new CameraBarcodeReaderView{IsDetecting=true,Options=new BarcodeReaderOptions{Formats=BarcodeFormats.All}};camera.BarcodesDetected+=Detected;Content=new Grid{RowDefinitions={new RowDefinition{Height=GridLength.Star},new RowDefinition{Height=GridLength.Auto}},Children={camera,result}};Grid.SetRow(result,1);} void Detected(object? sender,BarcodeDetectionEventArgs e){var value=e.Results.FirstOrDefault()?.Value;if(scanning||String.IsNullOrWhiteSpace(value))return;scanning=true;MainThread.BeginInvokeOnMainThread(async()=>{try{var x=await api.PostAsync<DriverScanResultDto>($"driver/trips/{trip.Id}/scan",new{qrValue=value,phase});result.Text=x?.Message??"Scan could not be processed.";result.TextColor=x?.Success==true?Colors.DarkGreen:Colors.Firebrick;}catch(Exception ex){result.Text=ex.Message;result.TextColor=Colors.Firebrick;}finally{await Task.Delay(1200);scanning=false;}});} }
public sealed class HouseMasterHomePage : ContentPage { readonly MobileApiClient api; readonly SessionService session; public HouseMasterHomePage(MobileApiClient a,SessionService s,string name){api=a;session=s;Title="Residence emergency";Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text="Residence emergency",Style=(Style)Application.Current!.Resources["Headline"],HorizontalTextAlignment=TextAlignment.Start},new Button{Text="Emergency alerts",Command=new Command(async()=>await Navigation.PushAsync(new HouseMasterAlertsPage(api)))},new Button{Text="Emergency roll call",Command=new Command(async()=>await Navigation.PushAsync(new HouseMasterResidencesPage(api)))},new Button{Text="Sign out",Command=new Command(async()=>{session.Clear();api.SetToken(null);await Navigation.PushAsync(new LoginPage(api,session));})}}};} }
public sealed class HouseMasterAlertsPage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public HouseMasterAlertsPage(MobileApiClient a){api=a;Title="Emergency alerts";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Title").Bind(TextCell.DetailProperty,"Message"));Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<HouseMasterAlertDto>>("housemaster/alerts")??[];list.ItemsSource=x;state.Text=x.Count==0?"No active residence alerts.":"";}catch{state.Text="Unable to load emergency alerts.";}} }
public sealed class HouseMasterResidencesPage : ContentPage { readonly MobileApiClient api; readonly CollectionView list=new(); readonly Label state=new(); public HouseMasterResidencesPage(MobileApiClient a){api=a;Title="Emergency roll call";list.ItemTemplate=new DataTemplate(()=>new TextCell().Bind(TextCell.TextProperty,"Name"));list.SelectionChanged+=async(_,e)=>{if(e.CurrentSelection.FirstOrDefault()is HouseMasterResidenceDto x)await Navigation.PushAsync(new EmergencyRollCallPage(api,x));};Content=new VerticalStackLayout{Padding=20,Children={state,list}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<HouseMasterResidenceDto>>("housemaster/residences")??[];list.ItemsSource=x;state.Text=x.Count==0?"No residence is assigned to you.":"";}catch{state.Text="Unable to load your residences.";}} }
public sealed class EmergencyRollCallPage : ContentPage { readonly MobileApiClient api; readonly HouseMasterResidenceDto residence; readonly VerticalStackLayout rows=new(){Spacing=8}; readonly Label state=new(); public EmergencyRollCallPage(MobileApiClient a,HouseMasterResidenceDto r){api=a;residence=r;Title="Emergency roll call";Content=new ScrollView{Content=new VerticalStackLayout{Padding=20,Spacing=12,Children={new Label{Text=r.Name,Style=(Style)Application.Current!.Resources["SubHeadline"],HorizontalTextAlignment=TextAlignment.Start},state,rows}}};} protected override async void OnAppearing(){base.OnAppearing();try{var x=await api.GetAsync<List<RollCallStudentDto>>($"housemaster/residences/{residence.Id}/rollcall")??[];rows.Children.Clear();foreach(var student in x)rows.Children.Add(new Button{Text="Mark present · "+student.Name,Command=new Command(async()=>await Mark(student))});state.Text=x.Count==0?"No active students are listed.":"";}catch{state.Text="Unable to load the emergency roll call.";}} async Task Mark(RollCallStudentDto student){try{await api.PostAsync<object>($"housemaster/residences/{residence.Id}/rollcall/{student.StudentId}",null);state.Text=student.Name+" marked present.";}catch(Exception ex){state.Text=ex.Message;}} }
